from binascii import crc_hqx

def key_slot(key: bytes) -> int:
    # Hash tag: if the key contains {...}, only that part is hashed, so
    # user:{42}:cart and user:{42}:profile share a slot and multi-key ops work.
    start = key.find(b"{")
    if start != -1:
        end = key.find(b"}", start + 1)
        if end > start + 1:
            key = key[start + 1:end]
    return crc_hqx(key, 0) % 16384          # CRC16-XMODEM; key_slot(b"foo") == 12182

class SmartClient:
    def __init__(self, seed_node):
        self.slots = fetch_slot_map(seed_node)      # CLUSTER SHARDS: slot -> primary

    def call(self, cmd: str, key: bytes, *args, max_redirects: int = 5):
        node = self.slots[key_slot(key)]            # one hop, no proxy
        for _ in range(max_redirects):
            reply = node.send(cmd, key, *args)
            if reply.is_error("MOVED"):             # slot has a new owner: my map is stale
                self.slots = fetch_slot_map(node)
                node = self.slots[key_slot(key)]
            elif reply.is_error("ASK"):             # slot is mid-migration: one-off hop,
                node = connect(reply.address)       # and the map stays as it is
                node.send("ASKING")
            else:
                return reply
        raise RuntimeError("too many redirects: the cluster is reconfiguring")
